"""Exact solvers written from the problem definitions.

solve_dominating_set: brute force over subsets of size <= k.
solve_sat: DPLL (exact).  A plain 2^m enumeration is also included as
solve_sat_bruteforce for cross-checking on tiny formulas.
"""
from itertools import combinations


def solve_dominating_set(instance):
    n = instance["n"]
    edges = instance["edges"]
    k = instance["k"]
    if k < 0:
        return False
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)
    vertices = list(range(n))
    for size in range(0, min(k, n) + 1):
        for combo in combinations(vertices, size):
            chosen = set(combo)
            dominated = set(chosen)
            for v in chosen:
                dominated |= adj[v]
            if len(dominated) == n:
                return True
    return False


def solve_sat_bruteforce(instance):
    m = instance["num_vars"]
    clauses = instance["clauses"]
    for mask in range(1 << m):
        ok = True
        for clause in clauses:
            sat = False
            for lit in clause:
                var = abs(lit)
                val = bool((mask >> (var - 1)) & 1)
                if (lit > 0) == val:
                    sat = True
                    break
            if not sat:
                ok = False
                break
        if ok:
            return True
    return False


def solve_sat(instance):
    """DPLL over the CNF."""
    m = instance["num_vars"]
    clauses = [list(c) for c in instance["clauses"]]

    def simplify(clauses, var, value):
        out = []
        for clause in clauses:
            if (var if value else -var) in clause:
                continue  # clause satisfied
            new = [l for l in clause if l != (-var if value else var)]
            out.append(new)
        return out

    def dpll(clauses, assignment):
        # unit propagation
        while True:
            unit = None
            for clause in clauses:
                if len(clause) == 0:
                    return None
                if len(clause) == 1:
                    unit = clause[0]
                    break
            if unit is None:
                break
            var = abs(unit)
            value = unit > 0
            assignment[var] = value
            clauses = simplify(clauses, var, value)
        # pure literal elimination
        while True:
            polar = {}
            for clause in clauses:
                for l in clause:
                    polar.setdefault(abs(l), set()).add(l > 0)
            pure = None
            for var, signs in polar.items():
                if len(signs) == 1:
                    pure = (var, signs.pop())
                    break
            if pure is None:
                break
            var, value = pure
            assignment[var] = value
            clauses = simplify(clauses, var, value)
        if not clauses:
            return assignment
        # choose a variable
        var = abs(clauses[0][0])
        for value in (True, False):
            new_clauses = simplify(clauses, var, value)
            res = dpll(new_clauses, dict(assignment, **{var: value}))
            if res is not None:
                return res
        return None

    result = dpll(clauses, {})
    return result is not None
