    edges = instance["edges"]
    k = instance["k"]

    # k < 0 is always a NO instance -> return an unsatisfiable CNF.
    if k < 0:
        return {"num_vars": 0, "clauses": [[]]}

    # Build adjacency lists.
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    def domination_clauses():
        clauses = []
        for v in range(n):
            clause = [v + 1]
            for u in adj[v]:
                clause.append(u + 1)
            clauses.append(clause)
        return clauses

