    for i in range(1, n + 1):
        clauses.append([-i, s(i, 1)])

    # (B) s(i-1, j) -> s(i, j)
    for i in range(2, n + 1):
        for j in range(1, k + 1):
            clauses.append([-s(i - 1, j), s(i, j)])

    # (C) x_i and s(i-1, j-1) -> s(i, j)
    for i in range(2, n + 1):
